<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import { restockApi } from '../../api/restock.api'
import type { RestockPreviewItem } from '../../models/restock'

type AllocatedItem=RestockPreviewItem&{allocated:number;shortage:number;allocations:Array<{rank:number;num:number}>;canUpgrade:boolean}
const date=ref(''),serialNo=ref(1),itemIds=ref<number[]>([]),items=ref<RestockPreviewItem[]>([]),strategy=ref<1|2|3>(1),manualUpgrade=ref<string[]>([]),loading=ref(true),error=ref(''),submitting=ref(false)
const rankText=(rank:number)=>['','A级','B级','C级','D级','E级'][rank]||`${rank}级`
const allocatedItems=computed<AllocatedItem[]>(()=>{const stocks=new Map<number,number>();items.value.flatMap(item=>item.inventoryList).forEach(inv=>stocks.set(inv.productId,Math.max(stocks.get(inv.productId)||0,inv.available)));return items.value.map(item=>{let remaining=item.needNum;const allocations:Array<{rank:number;num:number}>=[];const maxUpgrade=strategy.value===3?2:strategy.value===2?1:manualUpgrade.value.includes(item.key)?2:0;item.inventoryList.filter(inv=>inv.rank<=item.rank&&item.rank-inv.rank<=maxUpgrade).sort((a,b)=>b.rank-a.rank).forEach(inv=>{if(remaining<=0)return;const available=stocks.get(inv.productId)||0;const num=Math.min(remaining,available);if(num){allocations.push({rank:inv.rank,num});stocks.set(inv.productId,available-num);remaining-=num}});const higher=item.inventoryList.some(inv=>inv.rank<item.rank&&inv.available>0);return{...item,allocated:item.needNum-remaining,shortage:remaining,allocations,canUpgrade:higher}})})
const totalNeed=computed(()=>items.value.reduce((sum,item)=>sum+item.needNum,0)),totalAllocated=computed(()=>allocatedItems.value.reduce((sum,item)=>sum+item.allocated,0)),insufficient=computed(()=>allocatedItems.value.filter(item=>item.shortage>0)),zones=computed(()=>[...new Set(items.value.map(item=>`${Number(item.zone)}区`))])
function changeStrategy(value:1|2|3){strategy.value=value;manualUpgrade.value=[]}
function toggleUpgrade(item:AllocatedItem){if(strategy.value!==1||!item.canUpgrade)return;manualUpgrade.value=manualUpgrade.value.includes(item.key)?manualUpgrade.value.filter(key=>key!==item.key):[...manualUpgrade.value,item.key]}
async function submit(){if(submitting.value)return;let content='请确认补货方式无误，提交后无法撤销。';if(allocatedItems.value.some(item=>item.canUpgrade&&item.shortage>0)&&strategy.value===1)content='存在可提级补货但尚未提级，请确认后提交。';else if(totalAllocated.value<20)content='当前可匹配补货数量少于20扎，是否继续提交？';uni.showModal({title:'提交确认',content,confirmText:'确认提交',success:async result=>{if(!result.confirm)return;submitting.value=true;try{await restockApi.submitPlan(date.value,itemIds.value,strategy.value);uni.showToast({title:'提交成功',icon:'success'});setTimeout(()=>uni.navigateBack(),700)}finally{submitting.value=false}}})}
onLoad(async query=>{date.value=String(query?.date||new Date().toISOString().slice(0,10));itemIds.value=uni.getStorageSync('restockSubmitItems')||[];uni.removeStorageSync('restockSubmitItems');if(!itemIds.value.length){error.value='缺少补货明细';loading.value=false;return}try{const preview=await restockApi.preview(date.value,itemIds.value);serialNo.value=preview.serialNo;items.value=preview.items}catch(e){error.value=e instanceof Error?e.message:'补货库存匹配失败'}finally{loading.value=false}})
</script>

<template><view class="page">
  <WareState v-if="loading" type="loading" title="正在匹配到场库存"/><WareState v-else-if="error" type="error" title="无法生成补货方案" :description="error"/>
  <template v-else><view class="summary"><view class="summary-title"><text class="eyebrow">提交补货</text><strong>#{{serialNo}}</strong></view><view class="summary-total"><strong>{{totalAllocated}}</strong><small>/{{totalNeed}} 扎可补</small></view><view class="summary-grid"><view><text>库存不足</text><b>{{insufficient.length}}类 · {{insufficient.reduce((sum,item)=>sum+item.shortage,0)}}扎</b></view><view><text>补货分区</text><b>{{zones.join('、')}}</b></view></view></view>
  <view class="strategy"><text>匹配策略</text><view :class="{active:strategy===1}" @click="changeStrategy(1)"><i/>手动提级</view><view :class="{active:strategy===2}" @click="changeStrategy(2)"><i/>提1级补货</view><view :class="{active:strategy===3}" @click="changeStrategy(3)"><i/>提1/2级补货</view></view>
  <view class="table-head"><text>商品详情</text><text>需补数量</text><text>到场货库存</text><text>操作</text></view>
  <view class="cards"><view v-for="item in allocatedItems" :key="item.key" class="card"><view class="main"><view class="product"><strong>{{item.productName}}<text>{{rankText(item.rank)}}</text></strong><small>{{item.skuConfig}}</small></view><view class="need"><strong>{{item.needNum}}</strong><small>扎</small></view><view class="stock"><strong :class="{danger:item.shortage}">{{item.allocated}}</strong><small :class="item.shortage?'bad':'ok'">{{item.shortage?`缺 ${item.shortage}扎`:'充足'}}</small></view><view class="operation"><button v-if="strategy===1&&item.canUpgrade" :class="{active:manualUpgrade.includes(item.key)}" @click.stop="toggleUpgrade(item)">{{manualUpgrade.includes(item.key)?'取消提级':'提级'}}</button><text v-else>{{strategy===1?'—':'自动'}}</text></view></view><view v-if="item.allocations.length" class="allocation"><text v-for="entry in item.allocations" :key="entry.rank">{{rankText(entry.rank)}}匹配 {{entry.num}}扎</text></view></view></view>
  <view class="bottom"><view><text>预计补货</text><strong>{{totalAllocated}}扎</strong></view><button :disabled="!items.length" @click="submit">确认提交</button></view></template>
</view></template>

<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx 24rpx 150rpx}.summary{padding:24rpx;border-radius:22rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.summary-title{display:flex;align-items:center;justify-content:space-between}.eyebrow{color:var(--wms-text-secondary);font-size:21rpx}.summary-title strong{color:var(--wms-text);font-size:27rpx}.summary-total{display:flex;align-items:baseline;gap:7rpx;margin-top:5rpx}.summary-total strong{color:var(--wms-primary-700);font-size:44rpx}.summary-total small{color:var(--wms-text);font-size:21rpx}.summary-grid{display:grid;grid-template-columns:1fr 1fr;margin-top:18rpx;padding-top:16rpx;border-top:1rpx solid var(--wms-border)}.summary-grid view{display:flex;flex-direction:column;gap:6rpx}.summary-grid view+view{padding-left:20rpx;border-left:1rpx solid var(--wms-border)}.summary-grid text{color:var(--wms-text-secondary);font-size:19rpx}.summary-grid b{font-size:21rpx}.strategy{display:flex;align-items:center;gap:16rpx;margin-top:22rpx;overflow-x:auto}.strategy>text{flex:none;font-size:22rpx;font-weight:700}.strategy view{display:flex;flex:none;align-items:center;gap:6rpx;color:var(--wms-text-secondary);font-size:20rpx}.strategy i{box-sizing:border-box;width:25rpx;height:25rpx;border:2rpx solid #aebbb8;border-radius:50%}.strategy .active{color:var(--wms-primary-700)}.strategy .active i{border:7rpx solid var(--wms-primary-700)}.table-head,.main{display:grid;grid-template-columns:minmax(0,1fr) 100rpx 130rpx 92rpx;align-items:center;column-gap:10rpx}.table-head{margin-top:22rpx;padding:14rpx 18rpx;border-radius:12rpx 12rpx 0 0;background:var(--wms-primary-700);color:#fff;font-size:19rpx;font-weight:700;text-align:center}.table-head text:first-child{text-align:left}.cards{display:flex;flex-direction:column;gap:2rpx}.card{padding:18rpx;border-radius:0;background:#fff}.card:last-child{border-radius:0 0 16rpx 16rpx}.product{min-width:0}.main strong,.main small{display:block}.product strong{overflow:hidden;font-size:22rpx;white-space:nowrap;text-overflow:ellipsis}.product strong text{margin-left:6rpx;color:var(--wms-primary-700);font-size:18rpx}.product small{overflow:hidden;margin-top:6rpx;color:var(--wms-text-secondary);font-size:17rpx;white-space:nowrap;text-overflow:ellipsis}.need,.stock,.operation{text-align:center}.need strong,.stock strong{display:inline;font-size:24rpx}.need small{display:inline;margin-left:3rpx;color:var(--wms-text-secondary);font-size:17rpx}.stock strong.danger{color:var(--wms-danger)}.stock small{display:block;margin-top:4rpx;font-size:16rpx}.stock .bad{color:var(--wms-danger)}.stock .ok{color:var(--wms-primary-700)}.operation button{box-sizing:border-box;min-width:76rpx;height:52rpx;margin:0;padding:0 10rpx;border:1rpx solid var(--wms-primary-700);border-radius:9rpx;background:#fff;color:var(--wms-primary-700);font-size:18rpx;line-height:50rpx}.operation button:after{border:0}.operation button.active{background:var(--wms-primary-700);color:#fff}.operation>text{color:var(--wms-text-secondary);font-size:18rpx}.allocation{display:flex;gap:9rpx;margin-top:13rpx;padding-top:12rpx;border-top:1rpx solid var(--wms-border);flex-wrap:wrap}.allocation text{padding:6rpx 10rpx;border-radius:7rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:18rpx}.bottom{position:fixed;right:0;bottom:0;left:0;z-index:10;display:flex;align-items:center;justify-content:space-between;padding:14rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));border-top:1rpx solid var(--wms-border);background:#fff}.bottom text,.bottom strong{display:block}.bottom text{color:var(--wms-text-secondary);font-size:18rpx}.bottom strong{margin-top:3rpx;font-size:24rpx}.bottom button{width:420rpx;height:72rpx;margin:0;border:0;border-radius:14rpx;background:var(--wms-primary-700);color:#fff;font-size:24rpx;line-height:72rpx}.bottom button[disabled]{background:#cbd7d4}
</style>
